import {firebaseConfig,region,appCheckSiteKey} from './config.js';
import {requestChangeKey} from './change-key.js';
const $=id=>document.getElementById(id),money=(n,c=$('commission-currency').value)=>new Intl.NumberFormat('es-CR',{style:'currency',currency:c}).format(n/100),date=d=>d?new Date(d).toLocaleDateString('es-CR',{timeZone:'America/Costa_Rica'}):'—',month=d=>d?new Intl.DateTimeFormat('en-CA',{timeZone:'America/Costa_Rica',year:'numeric',month:'2-digit'}).format(new Date(d)):'';
let call,data,visible=[],selected=new Set(),busy=false,stamp=0,payRequest=null;
function status(s){$('state').textContent=s;}
function lock(value){busy=value;for(const id of ['seller','commission-currency','view','month','all-time','refresh-payments','percent','record-payment','confirm-payment','cancel-payment'])$(id).disabled=value;if(!value)$('record-payment').disabled=!selected.size||data?.bps==null;}
async function load(){const n=++stamp;selected.clear();data=null;render();status('Cargando ventas y pagos…');try{const result=await call({action:'list',seller:$('seller').value});if(n!==stamp)return;data=result;$('percent').value=data.bps==null?'':data.bps/100;$('payment-day').value=data.today;$('payment-day').max=data.today;render();status('Actualizado.');}catch(e){status(e.message||'No se pudo cargar.');}}
function render(){const paid=$('view').value==='paid',currency=$('commission-currency').value,m=$('month').value,search=$('search').value.trim().toLocaleLowerCase('es');$('month-label').firstChild.textContent=paid?'Mes de pago':'Mes de venta';$('payment-controls').hidden=paid;$('select-all').hidden=paid;$('rows').replaceChildren();$('summary').replaceChildren();if(!data){$('record-payment').disabled=true;visible=[];$('selected-total').textContent='';return;}
 const source=paid?data.paid.filter(s=>s.currency===currency).map(s=>({...s,amount:s,when:s.saleDate})):data.pending.map(s=>({...s,amount:s[currency],when:s.createdAt}));
 visible=source.filter(s=>(!m||(paid?s.day.slice(0,7):month(s.when))===m)&&(!search||[s.id,s.product,s.customerName].join(' ').toLocaleLowerCase('es').includes(search)));
 const ids=new Set(visible.map(s=>s.id));selected=new Set([...selected].filter(id=>ids.has(id)));let total=0,profit=0,commission=0,missing=0;for(const s of visible){total+=s.amount?.totalMinor||0;commission+=s.amount?.commissionMinor||0;if(s.amount?.profitMinor==null)missing++;else profit+=s.amount.profitMinor;
 const tr=document.createElement('tr'),check=document.createElement('input');check.type='checkbox';check.checked=paid||selected.has(s.id);check.disabled=paid||!s.amount||data.bps==null||busy;check.setAttribute('aria-label','Seleccionar '+s.product);check.onchange=()=>{check.checked?selected.add(s.id):selected.delete(s.id);selection();};const cell=document.createElement('td');cell.append(check);tr.append(cell);
 const values=[s.product+(s.customerName?' · '+s.customerName:'')+' · '+s.id,date(s.when),s.amount?money(s.amount.totalMinor):'No disponible',s.amount?.profitMinor==null?'Sin costo registrado':money(s.amount.profitMinor),s.amount?money(s.amount.commissionMinor)+(paid?' · '+s.bps/100+'%':''):'—',paid?'Pagada · '+s.day:'Pendiente'];for(const v of values){const td=document.createElement('td');td.textContent=v;tr.append(td);}$('rows').append(tr);}
 for(const [label,value]of [['Total vendido',money(total)],['Ganancia bruta',money(profit)+(missing?' *':'')],[paid?'Comisiones pagadas':'Acumulado por pagar',data.bps==null&&!paid?'Definí el %':money(commission)],['Ventas',String(visible.length)]]){const a=document.createElement('article');a.className='panel';const t=document.createElement('span'),v=document.createElement('strong');t.textContent=label;v.textContent=value;a.append(t,v);$('summary').append(a);}
 $('count').textContent=visible.length+' ventas'+(missing?' · * Hay costos sin registrar':'');$('paid-lifetime').textContent='Pagado a '+$('seller').value+' en todo el tiempo: '+money(data.paid.filter(p=>p.currency===currency).reduce((n,p)=>n+p.commissionMinor,0))+' · '+currency;$('rate-note').textContent=data.bps==null?'Sin porcentaje configurado. Guardalo para habilitar pagos.':'Porcentaje guardado: '+data.bps/100+'%. Los pagos anteriores conservan su porcentaje.';selection();}
function selection(){const sum=visible.filter(s=>selected.has(s.id)).reduce((n,s)=>n+(s.amount?.commissionMinor||0),0);$('selected-total').textContent=selected.size+' seleccionadas · '+money(sum);$('record-payment').disabled=busy||!selected.size||data?.bps==null;$('select-all').checked=visible.length>0&&visible.every(s=>selected.has(s.id));}
$('select-all').onchange=()=>{selected.clear();if($('select-all').checked)visible.filter(s=>s.amount).slice(0,100).forEach(s=>selected.add(s.id));render();};
for(const id of ['commission-currency','view','month','search'])$(id).addEventListener(id==='search'?'input':'change',()=>{selected.clear();render();});$('seller').onchange=load;$('refresh-payments').onclick=load;$('all-time').onclick=()=>{$('month').value='';render();};
$('rate-form').onsubmit=async e=>{e.preventDefault();if(busy)return;lock(true);try{await call({action:'rate',seller:$('seller').value,percent:$('percent').value},true);await load();status('Porcentaje guardado.');}catch(e){status(e.message);}finally{lock(false);}};
$('record-payment').onclick=()=>{if(!data||!selected.size||!$('payment-day').value)return status('Seleccioná ventas y fecha de pago.');$('confirm-text').textContent=$('seller').value+' · '+$('selected-total').textContent+' · '+data.bps/100+'% sobre el total de cada venta.';payRequest={action:'pay',seller:$('seller').value,currency:$('commission-currency').value,bps:data.bps,saleIds:[...selected],totals:Object.fromEntries(visible.filter(s=>selected.has(s.id)).map(s=>[s.id,s.amount.totalMinor])),day:$('payment-day').value,requestId:crypto.randomUUID()};$('payment-confirm').showModal();};$('cancel-payment').onclick=()=>$('payment-confirm').close();$('payment-confirm').addEventListener('cancel',e=>{if(busy)e.preventDefault();});
$('confirm-payment').onclick=async()=>{if(busy)return;lock(true);try{await call(payRequest,true);$('payment-confirm').close();await load();status('Pago registrado. Las ventas seleccionadas pasaron al historial.');}catch(e){status(e.message);$('payment-confirm').close();}finally{lock(false);}};
async function start(){try{const base='https://www.gstatic.com/firebasejs/12.19.0/';const [a,b,c,d]=await Promise.all(['app','auth','functions','app-check'].map(n=>import(base+'firebase-'+n+'.js')));const app=a.initializeApp(firebaseConfig);d.initializeAppCheck(app,{provider:new d.ReCaptchaEnterpriseProvider(appCheckSiteKey),isTokenAutoRefreshEnabled:true});const auth=b.getAuth(app);await b.setPersistence(auth,b.browserSessionPersistence);await b.signInAnonymously(auth);const fn=c.httpsCallable(c.getFunctions(app,region),'ownerCommissions');call=async(payload,write=false)=>{const input={...payload};if(write)input.changeKey=await requestChangeKey();try{return (await fn(input)).data;}finally{delete input.changeKey;}};await load();}catch(e){status(e.message||'No se pudo conectar.');}}start();
